B.a9J=s(["1 Dose Thunfisch im eigenen Saft (ohne Salz/Oel abgegossen)","1 Ei","4-5 EL Haferflocken oder Reismehl"],t.s)
B.a7t=s(["Backofen auf 175 Grad C vorheizen.","Alles zu einer Masse verruehren.","Duenn auf ein Backblech streichen.","15 Minuten backen, abkuehlen, in kleine Wuerfel schneiden."],t.s)
B.awC=new A.hE(B.jF,"Thunfisch-Wuerfel","Herzhaft und sehr beliebt",B.a9J,B.a7t,"Im Kuehlschrank 3-4 Tage, einfrieren moeglich.","Perfekt als hochwertiges Trainings-Leckerli.")
B.aah=s(["150 g Kuerbispuree (ungesuesst, ohne Gewuerze)","200 g Vollkornmehl oder Haferflocken","1 Ei"],t.s)
B.a5p=s(["Backofen auf 180 Grad C vorheizen.","Zutaten zu einem Teig verkneten, ggf. etwas Mehl ergaenzen.","Ausrollen und Formen ausstechen.","20 Minuten backen, bis sie knusprig sind."],t.s)
B.awA=new A.hE(B.jF,"Kuerbis-Kekse","Gut fuer die Verdauung",B.aah,B.a5p,"Trocken gelagert 1-2 Wochen.",null)
B.acH=s(["1 geraspelte Karotte","1/2 geraspelter Apfel (ohne Kerngehaeuse)","150 g Haferflocken","1 Ei"],t.s)
B.a9Z=s(["Backofen auf 180 Grad C vorheizen.","Alles vermengen, kleine Taler formen.","18-20 Minuten backen, auskuehlen lassen."],t.s)
B.awE=new A.hE(B.jF,"Karotten-Apfel-Taler","Vitaminreich",B.acH,B.a9Z,"In einer Dose ca. 1 Woche.",null)
B.aaw=s(["3 EL Magerquark","frische Petersilie, fein gehackt","Haferflocken zum Binden"],t.s)
B.a5u=s(["Quark mit Petersilie verruehren.","So viele Haferflocken einkneten, bis eine formbare Masse entsteht.","Kleine Baellchen rollen."],t.s)
B.awz=new A.hE(B.tg,"Quark-Kraeuter-Baellchen","In 5 Minuten fertig",B.aaw,B.a5u,"Im Kuehlschrank 2-3 Tage.","Petersilie hilft sogar gegen Mundgeruch.")
B.a6V=s(["2 EL Erdnussbutter (OHNE Xylit/Suessstoff, ungesalzen)","Haferflocken"],t.s)
B.a9i=s(["Erdnussbutter mit so vielen Haferflocken verkneten, bis es formbar ist.","Kleine Kugeln rollen und kurz kalt stellen."],t.s)
B.awx=new A.hE(B.tg,"Erdnussbutter-Happen","Nur 2 Zutaten",B.a6V,B.a9i,"Im Kuehlschrank ca. 4 Tage.","WICHTIG: Erdnussbutter MUSS xylitfrei sein - Xylit ist giftig.")
B.a62=s(["Naturjoghurt (ohne Zucker)","einige Heidelbeeren oder Himbeeren"],t.s)
B.adH=s(["Joghurt mit den Beeren verruehren.","In eine Eiswuerfelform oder Silikonform fuellen.","Ueber Nacht einfrieren."],t.s)
B.awt=new A.hE(B.nn,"Joghurt-Beeren-Eis","Erfrischung fuer heisse Tage",B.a62,B.adH,"Im Gefrierfach mehrere Wochen.","Nur kleine Portionen geben - kalt und langsam schlecken lassen.")
B.a9d=s(["ungesalzene Gemuese- oder Huehnerbruehe (selbst gekocht, ohne Zwiebel)"],t.s)
B.aeN=s(["Bruehe abkuehlen lassen.","In Eiswuerfelformen fuellen und einfrieren."],t.s)
B.aww=new A.hE(B.nn,"Brueh-Eis","Herzhaft und fluessigkeitsspendend",B.a9d,B.aeN,"Im Gefrierfach mehrere Wochen.","Niemals Fertigbruehe mit Salz/Zwiebel verwenden.")
B.aeO=s(["etwas Magerquark oder Naturjoghurt","ein paar Haferflocken + Banane"],t.s)
B.ael=s(["Kong-Spielzeug mit der Masse fuellen.","Ueber Nacht einfrieren.","An heissen Tagen oder bei Langeweile geben."],t.s)
B.awu=new A.hE(B.nn,"Gefuellter Kong (gefroren)","Lange Beschaeftigung",B.aeO,B.ael,"Einzeln eingefroren mehrere Wochen.","Haelt aufgeregte Hunde lange und ruhig beschaeftigt.")
B.aeo=s(["250 g Rinderleber","1 Ei","3-4 EL Haferflocken"],t.s)
B.a79=s(["Leber puerieren, mit Ei und Haferflocken vermengen.","Duenn auf ein Backblech streichen.","Bei 170 Grad C ca. 20 Minuten backen.","Auskuehlen, in winzige Wuerfel schneiden."],t.s)
B.awB=new A.hE(B.nm,"Leber-Wuerfel","Das Highlight im Training",B.aeo,B.a79,"Im Kuehlschrank 3 Tage, sonst portionsweise einfrieren.","Sehr intensiv - nur kleine Mengen, sonst Durchfall.")
B.aeH=s(["fettarmer Kaese (z.B. Huettenkaese oder magerer Gouda)"],t.s)
B.a8d=s(["Kaese in sehr kleine Wuerfel schneiden.","Sparsam als Highlight im Training einsetzen."],t.s)
B.awv=new A.hE(B.nm,"Kaese-Tropfen","Mini-Belohnung",B.aeH,B.a8d,"Im Kuehlschrank wie normaler Kaese.","Nur kleine Mengen - Kaese ist fett- und kalorienreich.")
B.a7p=s(["mageres Rind- oder Huehnerfleisch in duennen Streifen"],t.s)
B.a4x=s(["Fleisch in duenne Streifen schneiden.","Im Backofen bei 70-80 Grad C mehrere Stunden trocknen (Tuer einen Spalt offen).","Fertig, wenn die Streifen ledrig-trocken sind."],t.s)
B.awy=new A.hE(B.nm,"Trockenfleisch-Streifen","Kauspass ohne Zusaetze",B.a7p,B.a4x,"Vollstaendig getrocknet 2-3 Wochen trocken gelagert.","Komplett durchtrocknen, sonst schimmelt es.")
